#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

# Run from Git Bash on Windows, NOT the WSL `bash` on PATH: user-secrets must land in your
# Windows profile, and the WSL distro here (podman machine) has no dotnet anyway.
#   & "$env:USERPROFILE\scoop\apps\git\current\bin\bash.exe" scripts/setup-discord-bot.sh

cd "$(dirname "${BASH_SOURCE[0]}")/.."

BOT_PROJECT="RngHelpdesk.DiscordBot"
API_PROJECT="RngHelpdesk.Api"
# Every value lives in `dotnet user-secrets`, never in a dotenv file: point the library's .env
# lookups at a non-file so `ask` never offers stale defaults from one.
ENV_FILE="/dev/null"
STORED=() # "project → key" written to user-secrets this run

if ! command -v dotnet >/dev/null 2>&1; then
  printf '%sdotnet not found on PATH. Run this from Git Bash, not WSL.%s\n' "$RED" "$RESET"
  exit 1
fi

# user_secret_get PROJECT KEY — print the current user-secret value (empty if unset).
user_secret_get() {
  dotnet user-secrets list --project "$1" 2>/dev/null \
    | grep -F "$2 = " | head -n1 | sed 's/^[^=]* = //' || true
}

# user_secret_set PROJECT KEY VALUE
user_secret_set() {
  dotnet user-secrets set "$2" "$3" --project "$1" >/dev/null
  STORED+=("$1 → $2")
  printf '  %s✓ saved%s %s → user-secrets of %s\n' "$GREEN" "$RESET" "$2" "$1"
}

# mask VALUE — first 4 chars + length, never the whole secret.
mask() { printf '%s… (%s chars)' "${1:0:4}" "${#1}"; }

# keep_existing PROJECT KEY LABEL — if KEY is already set, offer to keep it (success = keep).
keep_existing() {
  local current; current=$(user_secret_get "$1" "$2")
  [[ -n "$current" ]] || return 1
  say "A $3 is already saved: $(mask "$current")"
  confirm "Keep it and skip this step?"
}

banner "RngHelpdesk Discord bot — local secrets"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Discord application & bot token"
say "The bot needs its own Discord application. Its token becomes Discord:BotToken."
printf '\n'
if keep_existing "$BOT_PROJECT" "Discord:BotToken" "bot token"; then
  note "Keeping the saved bot token."
else
  open_url "https://discord.com/developers/applications"
  step "Already have an RNG Helpdesk application (the one whose token sits in the old"
  say  "  RngHelpdesk.DiscordBot/appsettings.Development.json)? Open that one — resetting its"
  say  "  token below also revokes the old token. Otherwise: New Application → name it → Create."
  step "Left sidebar → Bot → Token → Reset Token → confirm (2FA if asked) → Copy."
  step "On the same Bot page, leave all three Privileged Gateway Intents OFF."
  note "The token is shown only once. Lost it? Just reset it again."
  printf '\n'
  while :; do
    ask_secret BOT_TOKEN "Paste the bot token (hidden):"
    [[ "$BOT_TOKEN" =~ ^[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$ ]] && break
    warn "That doesn't look like a bot token (three dot-separated parts). Try again."
  done
  user_secret_set "$BOT_PROJECT" "Discord:BotToken" "$BOT_TOKEN"
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Invite the bot to your test server"
say "The bot must be a member of the server whose id you'll give it next."
note "You need the Manage Server permission on that server."
printf '\n'
if confirm "Is the bot already in your test server?"; then
  note "Skipping the invite."
else
  step "In the Developer Portal: General Information → Application ID → Copy."
  while :; do
    ask APP_ID "Paste the Application ID:"
    [[ "$APP_ID" =~ ^[0-9]{17,20}$ ]] && break
    warn "Application ids are 17–20 digits. Try again."
  done
  # Scopes bot + applications.commands, zero permissions: every reply is an interaction response.
  open_url "https://discord.com/oauth2/authorize?client_id=${APP_ID}&scope=bot+applications.commands&permissions=0"
  step "Pick your test server under 'Add to server' → Continue → Authorize."
  pause "Press Enter once the bot shows up in the server's member list"
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Server (guild) id"
say "Slash commands are registered to one server so they appear instantly: Discord:GuildId."
printf '\n'
if keep_existing "$BOT_PROJECT" "Discord:GuildId" "guild id"; then
  note "Keeping the saved guild id."
else
  step "In Discord: User Settings (gear) → Advanced → turn on Developer Mode."
  step "Right-click your test server's icon → Copy Server ID."
  printf '\n'
  while :; do
    ask GUILD_ID "Paste the Server ID:"
    [[ "$GUILD_ID" =~ ^[0-9]{17,20}$ ]] && break
    warn "Server ids are 17–20 digits. Try again."
  done
  user_secret_set "$BOT_PROJECT" "Discord:GuildId" "$GUILD_ID"
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Shared bot ↔ API secret"
say "The bot trades this secret for its API token (ADR 0008). Both projects need the same value:"
say "  $BOT_PROJECT → Api:BotApiKey     $API_PROJECT → DiscordBot:ApiKey"
warn "Anyone holding it can act as any member, admins included. It never leaves user-secrets."
printf '\n'
BOT_SIDE=$(user_secret_get "$BOT_PROJECT" "Api:BotApiKey")
API_SIDE=$(user_secret_get "$API_PROJECT" "DiscordBot:ApiKey")
if [[ -n "$BOT_SIDE" && "$BOT_SIDE" == "$API_SIDE" ]] && confirm "Both sides already share a secret ($(mask "$BOT_SIDE")). Keep it?"; then
  note "Keeping the existing shared secret."
else
  [[ -n "$BOT_SIDE" || -n "$API_SIDE" ]] && note "Replacing the existing (mismatched or unwanted) value(s)."
  if command -v openssl >/dev/null 2>&1; then
    SHARED_SECRET=$(openssl rand -base64 48 | tr -d '\n=+/')
  else
    SHARED_SECRET=$(head -c 48 /dev/urandom | base64 | tr -d '\n=+/')
  fi
  user_secret_set "$BOT_PROJECT" "Api:BotApiKey" "$SHARED_SECRET"
  user_secret_set "$API_PROJECT" "DiscordBot:ApiKey" "$SHARED_SECRET"
  note "Generated $(mask "$SHARED_SECRET") — you never need to see or type it."
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Stale bot appsettings.Development.json"
DEV_SETTINGS="$BOT_PROJECT/appsettings.Development.json"
if [[ ! -f "$DEV_SETTINGS" ]]; then
  note "No $DEV_SETTINGS — nothing to clean up."
else
  say "$DEV_SETTINGS is gitignored and loads on top of appsettings.json. Keys you didn't put in"
  say "user-secrets (like Api:BaseUrl) still come from it, so stale values there silently win."
  printf '\n'
  say "Keys it sets (values not shown):"
  grep -oE '"[A-Za-z]+"[[:space:]]*:' "$DEV_SETTINGS" | tr -d '":[:space:]' | sed 's/^/    /' || true
  printf '\n'
  warn "It also holds an old bot token. If you reset the token in stage 1 on that same app, it's dead."
  BACKUP="$HOME/rnghelpdesk-discordbot-appsettings.Development.json.bak"
  if confirm "Move it out of the repo to $BACKUP?"; then
    mv "$DEV_SETTINGS" "$BACKUP"
    printf '  %s✓ moved%s → %s (delete it once the bot works)\n' "$GREEN" "$RESET" "$BACKUP"
  else
    note "Left in place — remove at least its Api:BaseUrl (old port) or the bot can't reach the API."
  fi
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Check & run"
say "Saved configuration:"
for pair in "$BOT_PROJECT|Discord:BotToken" "$BOT_PROJECT|Discord:GuildId" \
            "$BOT_PROJECT|Api:BotApiKey" "$API_PROJECT|DiscordBot:ApiKey"; do
  project="${pair%%|*}"; key="${pair#*|}"
  value=$(user_secret_get "$project" "$key")
  if [[ -n "$value" ]]; then
    printf '    %s✓%s %-24s %s %s\n' "$GREEN" "$RESET" "$key" "$(mask "$value")" "$DIM($project)$RESET"
  else
    printf '    %s✗%s %-24s missing %s\n' "$RED" "$RESET" "$key" "$DIM($project)$RESET"
    SKIPPED+=("$key on $project — re-run this wizard")
  fi
done
printf '\n'
if dotnet dev-certs https --check --trust >/dev/null 2>&1; then
  note "HTTPS dev certificate is trusted."
else
  warn "HTTPS dev certificate isn't trusted — run: dotnet dev-certs https --trust"
fi
printf '\n'
say "Run order (three terminals, from the repo root):"
step "podman compose up -d"
step "dotnet run --project RngHelpdesk.Api --launch-profile http"
step "dotnet run --project RngHelpdesk.DiscordBot"
note "The bot logs 'Registered N slash commands to guild …' once it's ready. Try /ping first."
pause "Press Enter to finish"

finish
if (( ${#STORED[@]} )); then
  note "saved ${#STORED[@]} user-secret(s) this run:"
  for s in "${STORED[@]}"; do note "  - $s"; done
  printf '\n'
fi
